insert into daily_period_assignments (id,school_id,version_id,class_id,class_name,day_of_week,day_arabic,period_number,teacher_id,teacher_name,subject,updated_at)
select coalesce(e.id, 'v'||left(v.id::text,8)||'_'||s.class_id||'_'||s.day_of_week||'_p2'), 'zbt-primary', v.id, s.class_id, c.name, s.day_of_week, s.day_arabic, 2, s.teacher_id, t.display_name, s.subject, now()
from src s cross join v
join classes c on c.id=s.class_id
join teachers t on t.id=s.teacher_id
left join daily_period_assignments e on e.version_id=v.id and e.class_id=s.class_id and e.day_of_week=s.day_of_week and e.period_number=2
on conflict (id) do update set teacher_id=excluded.teacher_id, teacher_name=excluded.teacher_name, subject=excluded.subject, updated_at=now();
